import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.DMtjdCb-.js";const n="/help/assets/windows-release.ja.DBy3qUOy.png",g=JSON.parse('{"title":"1. PC に導入","description":"","frontmatter":{},"headers":[],"relativePath":"ja/desktop.md","filePath":"ja/desktop.md"}'),i={name:"ja/desktop.md"};function s(l,e,c,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_1-pc-に導入" tabindex="-1">1. PC に導入 <a class="header-anchor" href="#_1-pc-に導入" aria-label="Permalink to &quot;1. PC に導入&quot;">​</a></h1><p>この章ではブラウザーで AnimeMachine を開くところまで進めます。ダウンロードには後から qBittorrent や Ani-RSS を接続します。手持ちの動画は<a href="./collections.html">メディアフォルダーの追加</a>で利用できます。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows {#windows}&quot;">​</a></h2><ol><li><a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a> を開き、<strong>Assets</strong> を展開します。</li><li>ファイル名が <code>release-windows.zip</code> で終わるものをダウンロードします。</li><li>ZIP を右クリックして <strong>すべて展開</strong> を選び、<code>D:\\AnimeMachine</code> などの固定フォルダーへ展開します。</li><li>展開先の <strong><code>AnimeMachine.cmd</code></strong> をダブルクリックし、起動ウィンドウを開いたままにします。</li><li>ブラウザーで <strong><a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a></strong> を開きます。</li></ol><p><img src="'+n+'" alt="Windows の起動ウィンドウ、展開先とホーム画面" loading="lazy"></p><p><strong>確認する画面：</strong> AnimeMachine のログイン画面が表示されます。初期ユーザー名とパスワードは起動ウィンドウで確認し、<a href="./first-use.html">初回ログイン</a>へ進みます。</p><p>実行環境はパッケージに含まれています。次回も同じ起動ファイルを使用します。起動ウィンドウを閉じると停止します。</p><h2 id="macos-linux" tabindex="-1">macOS・Linux <a class="header-anchor" href="#macos-linux" aria-label="Permalink to &quot;macOS・Linux {#macos-linux}&quot;">​</a></h2><ol><li><a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">Python 3.11 以降</a>をインストールします。</li><li><a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a> から OS と CPU に合うパッケージをダウンロードして展開します。</li><li>macOS は <strong><code>AnimeMachine-macOS.command</code></strong> を開きます。Linux は展開先でターミナルを開いて実行します。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./AnimeMachine-Linux.sh</span></span></code></pre></div><ol start="4"><li>起動を待ち、<strong><a href="http://localhost:8787" target="_blank" rel="noreferrer">http://localhost:8787</a></strong> を開いて<a href="./first-use.html">ログイン</a>します。</li></ol><table tabindex="0"><thead><tr><th>CPU</th><th>パッケージの表記</th></tr></thead><tbody><tr><td>Intel・AMD</td><td><code>x86_64</code></td></tr><tr><td>Apple シリコン・その他の ARM PC</td><td><code>arm64</code> または <code>aarch64</code></td></tr></tbody></table><p>起動ファイルが必要な構成要素をインストールします。ターミナルを開いたままにし、終了時は <code>Ctrl+C</code> を押します。実行権限のエラーが出る場合は、展開先で Linux は <code>chmod +x AnimeMachine-Linux.sh</code>、macOS は <code>chmod +x AnimeMachine-macOS.command</code> を実行してから再起動します。</p><h2 id="別の機器から開く" tabindex="-1">別の機器から開く <a class="header-anchor" href="#別の機器から開く" aria-label="Permalink to &quot;別の機器から開く&quot;">​</a></h2><p>同じ LAN 内のスマートフォンでは、起動ウィンドウの <strong>LAN URL</strong> を使用します。例は <code>http://192.168.1.20:8787</code> です。スマートフォンで <code>localhost</code> を開くと、そのスマートフォン自身に接続します。</p><h2 id="この手順で困ったら" tabindex="-1">この手順で困ったら <a class="header-anchor" href="#この手順で困ったら" aria-label="Permalink to &quot;この手順で困ったら&quot;">​</a></h2><ul><li><strong>起動ファイルが見つからない：</strong> ZIP 全体を展開してからフォルダーを開きます。エクスプローラーの拡張子表示でファイル名も確認できます。</li><li><strong>ページが開かない：</strong> 起動ウィンドウが動いているか、表示されたポートと一致しているかを確認します。<a href="./troubleshooting.html#open-page">接続の確認</a>も参照してください。</li><li><strong>保存先を移したい：</strong> 終了後に <code>config.json</code> と <code>data</code> を含むフォルダー全体を移動し、新しい場所から起動します。</li></ul>',17)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
